import requests
import json

api_key = "74491e0c-9e0d-4ef2-9570-6a9c6833a9cd"
workflow_id = "b215cd6a-9b8b-4ff9-8a45-ca9e0726fb1d"

try:
    url = f"http://192.168.56.10:5001/api/v1/workflows/{workflow_id}/executions"
    headers = {"Authorization": f"Bearer {api_key}"}
    resp = requests.get(url, headers=headers, timeout=10)
    data = resp.json()

    if isinstance(data, list) and len(data) > 0:
        first = data[0]
        if isinstance(first, dict):
            print(first.get("execution_id", "KEY_NOT_FOUND"))
        else:
            print(f"NOT_DICT:{type(first).__name__}:{str(first)[:100]}")
    else:
        print(f"NO_DATA:{json.dumps(data)[:200]}")
except Exception as e:
    print(f"ERR:{str(e)}")
